fragment PostFields on Post {
    title
    excerpt
    slug
    date

    featuredImage {
        node {
            sourceUrl
            mediaDetails {
                height
                width
            }
        }
    }
}
query PostBySlug($id: ID!, $idType: PostIdType!) {
    post(id: $id, idType: $idType) {
        ...PostFields
        content
    }
    posts(first: 4, where: { orderby: { field: DATE, order: DESC } }) {
        edges {
            node {
                ...PostFields
            }
        }
    }
}
